const Arrow = ({ dir = 1 }: { dir?: number }) => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={dir < 0 ? { transform: "scaleX(-1)" } : undefined}>
    <path d="M5 12h14M13 6l6 6-6 6" />
  </svg>
)

function useReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const m = window.matchMedia("(prefers-reduced-motion: reduce)")
    const f = () => setReduced(m.matches)
    f()
    m.addEventListener("change", f)
    return () => m.removeEventListener("change", f)
  }, [])
  return reduced
}

function useInView(ref: { current: Element | null }, margin = "0px 0px -12% 0px") {
  const [seen, setSeen] = useState(false)
  useEffect(() => {
    const el = ref.current
    if (!el || seen) return
    if (!("IntersectionObserver" in window)) return setSeen(true)
    const io = new IntersectionObserver((es) => {
      if (es.some((e) => e.isIntersecting)) {
        setSeen(true)
        io.disconnect()
      }
    }, { rootMargin: margin, threshold: 0.2 })
    io.observe(el)
    return () => io.disconnect()
  }, [ref, margin, seen])
  return seen
}

// #region spring
// One step of a damped spring (semi-implicit Euler). Returns [position, velocity].
export function springStep(x: number, v: number, target: number, dt: number, k = 170, c = 24): [number, number] {
  const nv = v + ((target - x) * k - v * c) * dt
  return [x + nv * dt, nv]
}
// Signed distance of card i from the carousel position on a loop of n cards, in [-n/2, n/2).
export function loopOffset(i: number, pos: number, n: number) {
  return ((((i - pos) % n) + n + n / 2) % n) - n / 2
}
// Where a card sits on the curve, given its offset from the centre and the spacing to its neighbours.
export function cardPose(d: number, gap1: number, gap2: number) {
  const a = Math.abs(d)
  const s = d < 0 ? -1 : 1
  const x = s * (gap1 * Math.min(a, 1) + gap2 * Math.max(a - 1, 0))
  const scale = 1 - 0.14 * Math.min(a, 1) - 0.11 * Math.min(Math.max(a - 1, 0), 1.5)
  const rotate = s * (15 * Math.min(a, 1) + 5 * Math.min(Math.max(a - 1, 0), 1.5))
  const z = -a * 10
  const opacity = a <= 2.05 ? 1 : Math.max(0, 1 - (a - 2.05) / 0.35)
  return { x, scale, rotate, z, opacity }
}
// #endregion

// Rolling counter: every digit is a column that spins past 0–9 once and lands on its value.
const STRIP = "01234567890123456789".split("").map((c, i) => <span key={i}>{c}</span>)
function Roll({ value, on, delay = 0 }: { value: string; on: boolean; delay?: number }) {
  let k = 0
  return (
    <span className="hj-roll" aria-label={value} role="text">
      {value.split("").map((ch, i) => {
        if (!/\d/.test(ch)) return <span key={i} aria-hidden="true">{ch}</span>
        const at = k++
        return (
          <span key={i} className="hj-col" aria-hidden="true">
            <span className="hj-strip" style={{ transform: "translateY(" + (on ? -(10 + +ch) : 0) + "em)", transitionDelay: delay + at * 110 + "ms" }}>{STRIP}</span>
          </span>
        )
      })}
    </span>
  )
}

// Headline accent that morphs between phrases: the width glides, the old letters blur away, the new ones settle in.
function MorphPhrase({ phrases, reduced }: { phrases: string[]; reduced: boolean }) {
  const [i, setI] = useState(0)
  const [prev, setPrev] = useState(-1)
  const [widths, setWidths] = useState([] as number[])
  const wrap = useRef(null as HTMLSpanElement | null)
  const measure = useRef(null as HTMLSpanElement | null)
  useLayoutEffect(() => {
    const m = measure.current
    if (!m) return
    const read = () => setWidths(Array.from(m.children).map((c) => (c as HTMLElement).getBoundingClientRect().width))
    read()
    const fonts = (document as Document & { fonts?: FontFaceSet }).fonts
    fonts?.ready.then(read)
    window.addEventListener("resize", read)
    return () => window.removeEventListener("resize", read)
  }, [phrases])
  useEffect(() => {
    if (reduced || phrases.length < 2) return
    let visible = true
    const io = new IntersectionObserver((es) => (visible = es[0]?.isIntersecting ?? true))
    if (wrap.current) io.observe(wrap.current)
    const t = window.setInterval(() => {
      if (!visible || document.hidden) return
      setI((c) => {
        setPrev(c)
        return (c + 1) % phrases.length
      })
    }, 3400)
    return () => {
      window.clearInterval(t)
      io.disconnect()
    }
  }, [reduced, phrases.length])
  const letters = (s: string, out: boolean) =>
    s.split("").map((ch, k) => (
      <span key={k} className="hj-ch" style={{ animationDelay: (out ? k * 14 : 120 + k * 32) + "ms" }}>{ch}</span>
    ))
  return (
    <span className="hj-morph hj-serif" ref={wrap} style={widths[i] ? { width: widths[i] } : undefined} aria-live="off">
      <span className="hj-measure" ref={measure} aria-hidden="true">
        {phrases.map((p) => <span key={p}>{p}</span>)}
      </span>
      {prev >= 0 && prev !== i && <span key={"o" + prev + "-" + i} data-out="" aria-hidden="true">{letters(phrases[prev], true)}</span>}
      <span key={"i" + i} data-in={prev >= 0 ? "" : undefined}>{prev >= 0 ? letters(phrases[i], false) : phrases[i]}</span>
    </span>
  )
}

// The nav: an ink pill that clips an inverted copy of the labels, its two edges on separate springs,
// so it stretches toward where it is going and settles with a little give (adapted from ink-pill-navbar, minus gsap).
function Nav({ brand, active, compact, reduced, email, onGo }: { brand: string; active: string; compact: boolean; reduced: boolean; email: string; onGo: (id: string) => void }) {
  const row = useRef(null as HTMLDivElement | null)
  const ink = useRef(null as HTMLDivElement | null)
  const [hover, setHover] = useState("")
  const [open, setOpen] = useState(false)
  const s = useRef({ l: 0, r: 0, vl: 0, vr: 0, tl: 0, tr: 0, raf: 0, init: false })
  // over the hero the pill only follows the pointer; once the nav is a floating pill it marks the current section
  const target = hover || (compact ? active : "")
  useEffect(() => {
    const el = row.current
    const pill = ink.current
    if (!el || !pill) return
    const link = el.querySelector('[data-id="' + target + '"]') as HTMLElement | null
    const W = el.clientWidth
    const st = s.current
    if (link) {
      st.tl = link.offsetLeft
      st.tr = W - (link.offsetLeft + link.offsetWidth)
    } else {
      const mid = st.init ? st.l + (W - st.l - st.r) / 2 : W / 2
      st.tl = mid
      st.tr = W - mid
    }
    const paint = () => (pill.style.clipPath = "inset(0 " + st.r.toFixed(2) + "px 0 " + st.l.toFixed(2) + "px round 999px)")
    if (!st.init || reduced) {
      st.l = st.tl
      st.r = st.tr
      st.init = true
      paint()
      return
    }
    const goingRight = st.tl > st.l
    let last = performance.now()
    cancelAnimationFrame(st.raf)
    const tick = (now: number) => {
      const dt = Math.min(0.032, (now - last) / 1000)
      last = now
      ;[st.l, st.vl] = springStep(st.l, st.vl, st.tl, dt, goingRight ? 150 : 420, goingRight ? 17 : 34)
      ;[st.r, st.vr] = springStep(st.r, st.vr, st.tr, dt, goingRight ? 420 : 150, goingRight ? 34 : 17)
      paint()
      if (Math.abs(st.l - st.tl) + Math.abs(st.r - st.tr) + Math.abs(st.vl) + Math.abs(st.vr) > 0.3) st.raf = requestAnimationFrame(tick)
    }
    st.raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(st.raf)
  }, [target, reduced, compact])
  const items = (copy: boolean) =>
    LINKS.map((l) => (
      <a
        key={l.id}
        href={"#" + l.id}
        data-id={copy ? undefined : l.id}
        className="hj-link"
        tabIndex={copy ? -1 : undefined}
        aria-current={!copy && active === l.id ? "true" : undefined}
        onMouseEnter={copy ? undefined : () => setHover(l.id)}
        onFocus={copy ? undefined : () => setHover(l.id)}
        onBlur={copy ? undefined : () => setHover("")}
        onClick={(e) => {
          e.preventDefault()
          onGo(l.id)
        }}
      >
        {l.label}
        {l.badge && <span className="hj-badge">{l.badge}</span>}
      </a>
    ))
  return (
    <div className="hj-navwrap">
      <nav className="hj-nav" data-compact={compact ? "" : undefined} aria-label="Main">
        <a className="hj-brand" href="#home" onClick={(e) => (e.preventDefault(), onGo("home"))}>
          <i>
            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M2 20 9.5 7l3.6 6.2L15.5 9 22 20H2Z" /></svg>
          </i>
          {brand}
        </a>
        <div className="hj-links" ref={row} onMouseLeave={() => setHover("")}>
          {items(false)}
          <div className="hj-links-ink" ref={ink} aria-hidden="true">{items(true)}</div>
        </div>
        <a className="hj-login" href={"mailto:" + email + "?subject=Planning%20a%20trip"}>
          <svg viewBox="0 0 28 28" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden="true"><circle cx="14" cy="14" r="12.5" /><path d="M9 14h10M15 10l4 4-4 4" strokeLinecap="round" strokeLinejoin="round" /></svg>
          Log in
        </a>
        <button className="hj-menu" aria-label="Menu" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
          <i />
          <i />
        </button>
        <div className="hj-drop" data-open={open ? "" : undefined}>
          {LINKS.map((l) => (
            <a key={l.id} href={"#" + l.id} tabIndex={open ? 0 : -1} aria-current={active === l.id ? "true" : undefined} onClick={(e) => (e.preventDefault(), setOpen(false), onGo(l.id))}>
              {l.label}
              {l.badge && <span className="hj-badge">{l.badge}</span>}
            </a>
          ))}
        </div>
      </nav>
    </div>
  )
}

// Curved 3D coverflow on a spring. Drag, flick, arrow keys or the round buttons; it loops both ways.
function Coverflow({ tours, base, reduced, hidden, paused, onOpen }: { tours: Tour[]; base: string; reduced: boolean; hidden: number; paused: boolean; onOpen: (i: number, el: HTMLElement) => void }) {
  const n = tours.length
  const stage = useRef(null as HTMLDivElement | null)
  const cards = useRef([] as (HTMLDivElement | null)[])
  const m = useRef({ pos: 2, v: 0, target: 2, k: 1, gap1: 330, gap2: 236, raf: 0, last: 0, drag: false, sx: 0, sp: 0, moved: 0, vx: 0, lx: 0, lt: 0, hover: false, visible: true })
  const [active, setActive] = useState(2)
  const [h, setH] = useState(560)

  const paint = useCallback(() => {
    const st = m.current
    for (let i = 0; i < n; i++) {
      const el = cards.current[i]
      if (!el) continue
      const d = loopOffset(i, st.pos, n)
      const p = cardPose(d, st.gap1, st.gap2)
      el.style.transform = "translate3d(" + p.x.toFixed(2) + "px,0," + p.z.toFixed(1) + "px) rotateY(" + p.rotate.toFixed(2) + "deg) scale(" + (p.scale * st.k).toFixed(4) + ")"
      el.style.opacity = String(p.opacity)
      el.style.zIndex = String(100 - Math.round(Math.abs(d) * 10))
      el.style.pointerEvents = p.opacity < 0.5 ? "none" : ""
      if (Math.abs(d) < 0.5) el.setAttribute("data-center", "")
      else el.removeAttribute("data-center")
    }
  }, [n])

  const run = useCallback(() => {
    const st = m.current
    cancelAnimationFrame(st.raf)
    st.last = performance.now()
    const tick = (now: number) => {
      const dt = Math.min(0.032, (now - st.last) / 1000)
      st.last = now
      if (!st.drag) {
        if (reduced) {
          st.pos = st.target
          st.v = 0
        } else [st.pos, st.v] = springStep(st.pos, st.v, st.target, dt, 120, 21)
      }
      paint()
      if (st.drag || Math.abs(st.pos - st.target) > 0.0005 || Math.abs(st.v) > 0.0005) st.raf = requestAnimationFrame(tick)
      else {
        st.pos = st.target
        paint()
      }
    }
    st.raf = requestAnimationFrame(tick)
  }, [paint, reduced])

  const go = useCallback((t: number) => {
    const st = m.current
    st.target = t
    setActive(((Math.round(t) % n) + n) % n)
    run()
  }, [n, run])
  const step = useCallback((dir: number) => go(Math.round(m.current.target) + dir), [go])
  const goTo = useCallback((i: number) => {
    const st = m.current
    const r = Math.round(st.target)
    go(r + Math.round(loopOffset(i, r, n)))
  }, [go, n])

  useLayoutEffect(() => {
    const el = stage.current
    if (!el) return
    const fit = () => {
      const W = el.clientWidth
      const st = m.current
      const cw = W < 760 ? Math.min(330, W * 0.66) : Math.max(250, Math.min(372, W * 0.258))
      st.k = cw / 372
      st.gap1 = W < 760 ? cw * 0.74 : cw * 0.875
      st.gap2 = W < 760 ? cw * 0.56 : cw * 0.7
      setH(Math.round(488 * st.k + 24))
      paint()
    }
    fit()
    const ro = new ResizeObserver(fit)
    ro.observe(el)
    return () => ro.disconnect()
  }, [paint])

  useEffect(() => {
    const el = stage.current
    if (!el) return
    const io = new IntersectionObserver((es) => (m.current.visible = es[0]?.isIntersecting ?? true))
    io.observe(el)
    const t = window.setInterval(() => {
      const st = m.current
      if (reduced || paused || st.hover || st.drag || !st.visible || document.hidden) return
      step(1)
    }, 4800)
    return () => {
      window.clearInterval(t)
      io.disconnect()
    }
  }, [reduced, paused, step])

  useEffect(() => () => cancelAnimationFrame(m.current.raf), [])

  const down = (e: RPointerEvent) => {
    if (e.button !== 0) return
    const st = m.current
    st.drag = true
    st.sx = e.clientX
    st.sp = st.pos
    st.moved = 0
    st.vx = 0
    st.lx = e.clientX
    st.lt = performance.now()
    run()
  }
  const move = (e: RPointerEvent) => {
    const st = m.current
    if (!st.drag) return
    const dx = e.clientX - st.sx
    st.moved = Math.max(st.moved, Math.abs(dx))
    if (st.moved > 6) {
      stage.current?.setAttribute("data-drag", "")
      if (!stage.current?.hasPointerCapture(e.pointerId)) stage.current?.setPointerCapture(e.pointerId)
    }
    st.pos = st.sp - dx / st.gap1
    const now = performance.now()
    const dt = Math.max(1, now - st.lt)
    st.vx = 0.8 * ((e.clientX - st.lx) / dt) + 0.2 * st.vx
    st.lx = e.clientX
    st.lt = now
  }
  const up = () => {
    const st = m.current
    if (!st.drag) return
    st.drag = false
    stage.current?.removeAttribute("data-drag")
    if (st.moved > 6) {
      st.v = (-st.vx * 1000) / st.gap1
      go(Math.round(st.pos - st.vx * 0.35))
      window.setTimeout(() => (st.moved = 0), 0)
    } else run()
  }
  const clickCard = (i: number, e: RMouseEvent) => {
    if (m.current.moved > 6) return
    const card = cards.current[i]
    if (i === active && card && Math.abs(m.current.pos - m.current.target) < 0.05) onOpen(i, card)
    else goTo(i)
    e.stopPropagation()
  }

  return (
    <>
      <div
        className="hj-stage"
        ref={stage}
        style={{ height: h }}
        tabIndex={0}
        role="region"
        aria-roledescription="carousel"
        aria-label="Popular tours"
        onPointerDown={down}
        onPointerMove={move}
        onPointerUp={up}
        onPointerCancel={up}
        onMouseEnter={() => (m.current.hover = true)}
        onMouseLeave={() => (m.current.hover = false)}
        onKeyDown={(e) => {
          if (e.key === "ArrowRight") step(1)
          else if (e.key === "ArrowLeft") step(-1)
          else if (e.key === "Enter" && e.target === stage.current) {
            const c = cards.current[active]
            if (c) onOpen(active, c)
          } else return
          e.preventDefault()
        }}
      >
        {tours.map((t, i) => (
          <div
            key={t.id}
            ref={(el) => (cards.current[i] = el)}
            className="hj-card"
            data-hide={hidden === i ? "" : undefined}
            role="group"
            aria-roledescription="slide"
            aria-label={i + 1 + " of " + n + ": " + t.name}
            aria-hidden={i !== active ? "true" : undefined}
            onClick={(e) => clickCard(i, e)}
          >
            <img className="hj-card-img" src={base + t.id + ".webp"} alt={t.name} draggable={false} loading="lazy" decoding="async" width={372} height={488} />
            <img className="hj-card-blur" src={base + t.id + ".webp"} alt="" aria-hidden="true" draggable={false} loading="lazy" decoding="async" width={372} height={488} />
            <div className="hj-card-shade" />
            <div className="hj-card-body">
              <div className="hj-card-head">
                <h3>{t.name}</h3>
                <span className="hj-price">{t.price}</span>
              </div>
              <p>{t.blurb}</p>
              <div className="hj-chips">
                <span>{t.start}</span>
                <span>{t.days}</span>
              </div>
              <button className="hj-explore" tabIndex={i === active ? 0 : -1} aria-label={"Explore " + t.name}>
                Explore
                <Arrow />
              </button>
            </div>
          </div>
        ))}
      </div>
      <span className="hj-live" aria-live="polite">{tours[active].name + ", " + tours[active].price + ", " + tours[active].days}</span>
      <div className="hj-ctrl" data-rv="">
        <button className="hj-arrow" data-soft="" aria-label="Previous tour" onClick={() => step(-1)}>
          <Arrow dir={-1} />
        </button>
        <a className="hj-more" href={"mailto:" + MAIL + "?subject=The%20full%20list%20of%20tours"}>View More Tours</a>
        <button className="hj-arrow" aria-label="Next tour" onClick={() => step(1)}>
          <Arrow />
        </button>
      </div>
    </>
  )
}

type SheetRect = { left: number; top: number; width: number; height: number }

// The detail sheet: it starts exactly over the card it came from and grows into place (and shrinks back on close).
function TourSheet({ tour, index, total, from, base, email, reduced, getRect, onClosed }: { tour: Tour; index: number; total: number; from: SheetRect; base: string; email: string; reduced: boolean; getRect: () => SheetRect | null; onClosed: () => void }) {
  const [st, setSt] = useState("from")
  const [rect, setRect] = useState(from)
  const closeBtn = useRef(null as HTMLButtonElement | null)
  const [vp, setVp] = useState({ w: 1440, h: 900 })
  useLayoutEffect(() => {
    const fit = () => setVp({ w: window.innerWidth, h: window.innerHeight })
    fit()
    window.addEventListener("resize", fit)
    let r2 = 0
    const r1 = requestAnimationFrame(() => (r2 = requestAnimationFrame(() => setSt("open"))))
    return () => {
      cancelAnimationFrame(r1)
      cancelAnimationFrame(r2)
      window.removeEventListener("resize", fit)
    }
  }, [])
  const close = useCallback(() => {
    const r = getRect()
    if (r) setRect(r)
    setSt("closing")
    window.setTimeout(onClosed, reduced ? 10 : 680)
  }, [getRect, onClosed, reduced])
  useEffect(() => {
    if (st === "open") closeBtn.current?.focus({ preventScroll: true })
  }, [st])
  useEffect(() => {
    const key = (e: KeyboardEvent) => e.key === "Escape" && close()
    window.addEventListener("keydown", key)
    const html = document.documentElement
    const was = html.style.overflow
    html.style.overflow = "hidden"
    return () => {
      window.removeEventListener("keydown", key)
      html.style.overflow = was
    }
  }, [close])
  const small = vp.w < 860
  const W = small ? vp.w - 20 : Math.min(1010, vp.w - 40)
  const H = small ? vp.h - 20 : Math.min(640, vp.h - 48)
  const box: CSSProperties = st === "open" ? { left: (vp.w - W) / 2, top: (vp.h - H) / 2, width: W, height: H, borderRadius: 30 } : { ...rect, borderRadius: 26 }
  const [first, ...rest] = tour.name.split(" ")
  return (
    <>
      <div className="hj-veil" data-st={st} onClick={close} />
      <div className="hj-sheet" data-st={st} style={box} role="dialog" aria-modal="true" aria-label={tour.name}>
        <div className="hj-sheet-media">
          <img src={base + tour.id + ".webp"} alt="" width={720} height={900} />
          <div className="hj-sheet-cap">
            <h3>{tour.name}</h3>
            <span className="hj-price">{tour.price}</span>
          </div>
        </div>
        <button className="hj-x" ref={closeBtn} onClick={close} aria-label="Close">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" /></svg>
        </button>
        <div className="hj-sheet-body">
          <span className="hj-pill">{"Tour " + String(index + 1).padStart(2, "0") + " / " + String(total).padStart(2, "0")}</span>
          <h2>
            {first} <span className="hj-serif">{rest.join(" ")}</span>
          </h2>
          <p>{tour.blurb + " Designed and led by Kedhareswer, paced around you."}</p>
          <div className="hj-meta">
            <div><span>From</span><b>{tour.price}</b></div>
            <div><span>Length</span><b>{tour.days}</b></div>
            <div><span>Season</span><b>{tour.season}</b></div>
            <div><span>Highest</span><b>{tour.peak}</b></div>
          </div>
          <ul className="hj-plan">
            {tour.plan.map((p, k) => (
              <li key={k}><span>{"Day " + (k + 1)}</span>{p}</li>
            ))}
          </ul>
          <div className="hj-sheet-act">
            <a className="hj-book" href={"mailto:" + email + "?subject=" + encodeURIComponent("Trip: " + tour.name)}>Plan this trip with me</a>
          </div>
        </div>
      </div>
    </>
  )
}

const ABOUT = "Nepal is more than a destination — it's a journey. From Himalayan peaks to ancient cities, every experience brings you closer to its nature, culture and people."

export type HimalJourneysTemplateProps = {
  /** Height of the hero. A definite length, never a percentage. */
  height?: string
  /** Every call to action is a mailto: to this address. */
  email?: string
  /** Name in the nav and footer. */
  brand?: string
  /** Where the .webp pictures live. Point it at your own copy to self-host them. */
  assetBase?: string
  tours?: Tour[]
  className?: string
  style?: CSSProperties
}

export default function HimalJourneysTemplate({ height = "100svh", email = MAIL, brand = "Kedhar Trails", assetBase = SITE, tours = TOURS, className, style }: HimalJourneysTemplateProps) {
  const reduced = useReducedMotion()
  const root = useRef(null as HTMLDivElement | null)
  const heroBg = useRef(null as HTMLDivElement | null)
  const heroEnd = useRef(null as HTMLDivElement | null)
  const about = useRef(null as HTMLParagraphElement | null)
  const bentoRef = useRef(null as HTMLDivElement | null)
  const statsRef = useRef(null as HTMLDivElement | null)
  const [compact, setCompact] = useState(false)
  const [active, setActive] = useState("home")
  const [allIn, setAllIn] = useState(true)
  const [moving, setMoving] = useState(false)
  const [mfy, setMfy] = useState(false)
  const [sheet, setSheet] = useState(null as null | { i: number; from: SheetRect })
  const cardEls = useRef([] as (HTMLElement | null)[])
  const bentoOn = useInView(bentoRef)
  const statsOn = useInView(statsRef)

  // scroll reveals: a data attribute, so React never wipes it on re-render
  useEffect(() => {
    const el = root.current
    if (!el) return
    const items = Array.from(el.querySelectorAll("[data-rv]"))
    if (!("IntersectionObserver" in window)) return items.forEach((x) => x.setAttribute("data-in", ""))
    const io = new IntersectionObserver((es) => {
      for (const e of es)
        if (e.isIntersecting) {
          e.target.setAttribute("data-in", "")
          io.unobserve(e.target)
        }
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.1 })
    items.forEach((x) => io.observe(x))
    return () => io.disconnect()
  }, [])

  // nav state + which section is current
  useEffect(() => {
    const el = root.current
    const end = heroEnd.current
    if (!el || !end) return
    const io = new IntersectionObserver((es) => {
      for (const e of es) setCompact(!e.isIntersecting && e.boundingClientRect.top < 0)
    })
    io.observe(end)
    const spy = new IntersectionObserver((es) => {
      for (const e of es) if (e.isIntersecting) setActive((e.target as HTMLElement).dataset.spy || "home")
    }, { rootMargin: "-45% 0px -50% 0px" })
    el.querySelectorAll("[data-spy]").forEach((s) => spy.observe(s))
    return () => {
      io.disconnect()
      spy.disconnect()
    }
  }, [])

  // hero parallax and the about line inking in, both read from scroll on any scrolling ancestor
  useEffect(() => {
    let raf = 0
    const words = about.current ? Array.from(about.current.querySelectorAll(".hj-word")) as HTMLElement[] : []
    const frame = () => {
      raf = 0
      const vh = window.innerHeight
      const bg = heroBg.current
      if (bg && !reduced) {
        const r = bg.parentElement!.getBoundingClientRect()
        const y = Math.min(Math.max(-r.top, 0), r.height)
        bg.style.transform = "translate3d(0," + (y * 0.32).toFixed(1) + "px,0) scale(" + (1 + y / r.height / 12).toFixed(4) + ")"
      }
      if (about.current) {
        const r = about.current.getBoundingClientRect()
        const p = reduced ? 1 : Math.min(1, Math.max(0, (vh * 0.92 - r.top) / (vh * 0.5)))
        const lit = p * words.length
        words.forEach((w, k) => (w.style.opacity = String(0.18 + 0.82 * Math.min(1, Math.max(0, lit - k)))))
      }
    }
    const on = () => {
      if (!raf) raf = requestAnimationFrame(frame)
    }
    frame()
    document.addEventListener("scroll", on, { passive: true, capture: true })
    window.addEventListener("resize", on)
    return () => {
      cancelAnimationFrame(raf)
      document.removeEventListener("scroll", on, { capture: true } as EventListenerOptions)
      window.removeEventListener("resize", on)
    }
  }, [reduced])

  const goSection = useCallback((id: string) => {
    const target = root.current?.querySelector('[data-spy="' + id + '"]') as HTMLElement | null
    target?.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "start" })
  }, [reduced])

  const flip = () => {
    setMoving(true)
    setAllIn((v) => !v)
    window.setTimeout(() => setMoving(false), 260)
  }

  const rectOf = (el: HTMLElement | null): SheetRect | null => {
    if (!el) return null
    const r = el.getBoundingClientRect()
    return { left: r.left, top: r.top, width: r.width, height: r.height }
  }

  return (
    <div ref={root} className={"hj-root" + (className ? " " + className : "")} style={style}>
      <style>{CSS}</style>
      <Nav brand={brand} active={active} compact={compact} reduced={reduced} email={email} onGo={goSection} />

      <section className="hj-hero" data-spy="home" id="hj-home" style={{ height }}>
        <div className="hj-hero-bg" ref={heroBg}>
          <img src={assetBase + "hero.webp"} alt="Snow peaks at dawn above dark forested ridges" width={1600} height={900} />
        </div>
        <div className="hj-hero-tint" />
        <h1 className="hj-h1">
          <span>
            <span className="hj-rise" style={{ animationDelay: "250ms" }}>Nepal</span>{" "}
            <span className="hj-rise" style={{ animationDelay: "380ms" }}>
              <MorphPhrase phrases={PHRASES} reduced={reduced} />
            </span>
          </span>
          <span>
            {"Discover beyond the ordinary.".split(" ").map((w, k) => (
              <span key={k}>
                <span className="hj-rise" style={{ animationDelay: 520 + k * 90 + "ms" }}>{w}</span>{" "}
              </span>
            ))}
          </span>
        </h1>
        <div className="hj-hero-foot">
          <p className="hj-rise" style={{ animationDelay: "900ms" }}>
            Journeys through Nepal I design and lead myself — your pace, your path, your sense of wonder. Every trip feels personal, effortless, and truly yours.
          </p>
          <a className="hj-cta hj-rise" style={{ animationDelay: "1050ms" }} href={"mailto:" + email + "?subject=Build%20my%20trip"}>
            <span className="hj-cta-t">
              <span>Build my trip now</span>
              <span aria-hidden="true">Write to Kedhareswer</span>
            </span>
            <span className="hj-cta-dot" aria-hidden="true"><Arrow /></span>
          </a>
        </div>
        <div ref={heroEnd} style={{ position: "absolute", left: 0, right: 0, bottom: 70, height: 1 }} aria-hidden="true" />
      </section>

      <section className="hj-tours" data-spy="tours" id="hj-tours">
        <span className="hj-pill" data-rv="">Your journey</span>
        <h2 className="hj-h2" data-rv="" style={{ "--rd": "90ms" } as CSSProperties}>
          Discover <span className="hj-serif">Our Most</span>
          <br />
          <span className="hj-serif">Popular</span> Tours
        </h2>
        <div data-rv="" style={{ "--rd": "180ms" } as CSSProperties}>
          <Coverflow
            tours={tours}
            base={assetBase}
            reduced={reduced}
            hidden={sheet ? sheet.i : -1}
            paused={!!sheet}
            onOpen={(i, el) => {
              cardEls.current[i] = el
              const r = rectOf(el)
              if (r) setSheet({ i, from: r })
            }}
          />
        </div>
      </section>

      <section className="hj-about" data-spy="about" id="hj-about">
        <span className="hj-pill" data-rv="">About Nepal</span>
        <p ref={about} aria-label={ABOUT}>
          {ABOUT.split(" ").map((w, k) => (
            <span key={k} aria-hidden="true">
              <span className="hj-word">{w}</span>{" "}
            </span>
          ))}
        </p>
      </section>

      <section className="hj-bento" data-spy="experiences" id="hj-experiences" ref={bentoRef}>
        <div className="hj-tile hj-darkc" data-rv="">
          <div className="hj-darkc-top">
            <svg viewBox="0 0 30 30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <circle cx="6" cy="22" r="2.4" />
              <path d="M8.4 22H16a4 4 0 0 0 0-8h-3a4 4 0 0 1 0-8h9" strokeDasharray="2.6 2.6" />
              <path d="m20 3 4 3-4 3" />
            </svg>
            <span className="hj-switch">
              <span className="hj-switch-l" aria-hidden="true">
                <span style={{ transform: allIn ? "none" : "translateY(-100%)" }}>all-inclusive</span>
                <span style={{ transform: allIn ? "none" : "translateY(-100%)" }}>route only</span>
              </span>
              <button className="hj-track" role="switch" aria-checked={allIn} aria-label="All-inclusive" data-moving={moving ? "" : undefined} onClick={flip}>
                <span className="hj-knob" />
              </button>
            </span>
          </div>
          <div className="hj-darkc-copy">
            <p data-off={allIn ? undefined : ""} aria-hidden={!allIn}>
              Journeys made personal travel at your own pace, discover hidden places and experience Nepal beyond the usual routes — <b>authentic, personal and unforgettable.</b>
            </p>
            <p data-off={allIn ? "" : undefined} aria-hidden={allIn}>
              Just the route, the permits and me as your guide. Stay where you like, eat where you like — <b>light, flexible and still yours.</b>
            </p>
          </div>
          <a className="hj-tailor" href={"mailto:" + email + "?subject=" + (allIn ? "Tailor-made%20trip" : "Route-only%20trip")}>
            <span className="hj-tailor-t">
              <span style={{ transform: allIn ? "none" : "translateY(-100%)" }}>Tailor-Made</span>
              <span style={{ transform: allIn ? "none" : "translateY(-100%)" }} aria-hidden="true">Route Only</span>
            </span>
          </a>
        </div>

        <div className="hj-tile hj-photo" data-rv="" style={{ "--rd": "110ms" } as CSSProperties}>
          <img src={assetBase + "trekker.webp"} alt="Kedhareswer on a high trail below a snow peak" loading="lazy" width={720} height={900} />
          <button className="hj-mfy" aria-expanded={mfy} onClick={() => setMfy((v) => !v)} onMouseLeave={() => setMfy(false)}>
            <span className="hj-mfy-h">
              Made for You
              <span className="hj-mfy-plus" aria-hidden="true" />
            </span>
            <span className="hj-mfy-b">
              <div><span>Your guide</span>Kedhareswer</div>
              <div><span>Group size</span>2 – 8 people</div>
              <div><span>Languages</span>English · Hindi · Telugu</div>
              <div><span>Starts with</span>a 20-minute call</div>
            </span>
          </button>
        </div>

        <div className="hj-tile hj-statc" data-rv="" style={{ "--rd": "220ms" } as CSSProperties}>
          <div className="hj-big"><Roll value="50+" on={bentoOn} delay={300} /></div>
          <h4>Unique Experiences</h4>
          <p>Carefully selected journeys designed to reveal the real beauty, culture and spirit of Nepal.</p>
          <div className="hj-bars">
            {BARS.map((b, r) => (
              <div className="hj-bar" key={b.label}>
                <span>{b.label}</span>
                <span className="hj-dots" data-on={bentoOn ? "" : undefined} aria-hidden="true">
                  {Array.from({ length: b.dots }, (_, k) => (
                    <i key={k} style={{ transitionDelay: 450 + r * 160 + k * 45 + "ms" }} />
                  ))}
                </span>
                <span><Roll value={String(b.value)} on={bentoOn} delay={500 + r * 160} /></span>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="hj-stats" ref={statsRef} aria-label="In numbers">
        {STATS.map((s, k) => (
          <div className="hj-stat" key={s.label} data-rv="" style={{ "--rd": k * 90 + "ms" } as CSSProperties}>
            <strong><Roll value={s.value} on={statsOn} delay={k * 140} /></strong>
            <span>{s.label}</span>
          </div>
        ))}
      </section>

      <footer className="hj-foot" data-spy="contact" id="hj-contact">
        <div>
          <h5>
            Your Nepal, <span className="hj-serif">planned with me.</span>
          </h5>
          <a href={"mailto:" + email}>
            {email}
            <Arrow />
          </a>
        </div>
        <small>
          {brand} — tours designed and led by Kedhareswer
          <br />
          Kathmandu · Pokhara · the high trails
        </small>
      </footer>

      {sheet && (
        <TourSheet
          tour={tours[sheet.i]}
          index={sheet.i}
          total={tours.length}
          from={sheet.from}
          base={assetBase}
          email={email}
          reduced={reduced}
          getRect={() => rectOf(cardEls.current[sheet.i])}
          onClosed={() => setSheet(null)}
        />
      )}
    </div>
  )
}
